update public.content set data = $j$[["LR", "Rareté Secret, la plus haute des cartes classiques."], ["SSR", "Rareté Légendaire."], ["UR", "Rareté Mythique."], ["Transcendant", "Rareté au-dessus des LR, très rare."], ["Prestige (carte)", "Version prestige d'une carte non éveillée (ex. Boros prestige, Sukuna prestige). Elle ne peut pas se transformer en sa version éveillée et ne monte pas en étoiles."], ["Éveil / évolution", "Transformer une carte de base en sa version éveillée (ex. Boros → Boros Second Form) avec des objets, des cartes et du KI, depuis l'onglet Évolution. La version éveillée monte en étoiles comme les autres."], ["Étoiles", "Chaque étoile ajoute environ +8 % de PV et d'attaque à une carte (5★ ≈ ×1,4). On monte en sacrifiant des doublons."], ["Jetons Prestige", "Monnaie gagnée en ranked, en collectionnant (3 jetons par palier de 250 personnages) et en complétant des univers (3 jetons). 15 jetons = 1 booster Prestige."], ["Univers complété", "Posséder toutes les cartes d'un même anime (univers d'au moins 10 cartes) : bouton « Récupérer +3 » dans l'onglet Prestige."], ["KI", "Monnaie du jeu : marché, boosters, montées."], ["Recharge", "Nombre de tours avant de pouvoir relancer une technique."], ["Paralysie / gel", "La carte touchée perd son prochain tour."], ["Esquive", "L'attaque qui vise la carte est évitée (Rinnegan, DIMENSION, Ultra Instinct…)."], ["Voile (Haki de Xebec)", "Annule complètement le prochain coup reçu, contrôles compris."], ["Miroir", "Renvoie la prochaine attaque ou capacité sur son lanceur."], ["Brûlure / saignement", "Dégâts sur plusieurs tours. SLIME de Rimuru les purge."], ["Focus", "Toute l'équipe tape la même cible."], ["Two-shot", "Une carte qui meurt en deux coups."], ["Chambre", "Un étage du Château de l'infini : 3 gardiens dont les PV et l'attaque montent à chaque chambre."], ["Salle du temps", "Mode farm : chaque victoire rapporte du KI et parfois un booster."], ["Catégorie de technique", "Rôle d'une carte : dégâts, tank, healer, stunner, polyvalence."]]$j$::jsonb, updated_at=now() where key='lexique'